/**
 * Catálogo dimensional de engenharia (ISO 15, ISO 355, DIN 618, ISO 3448).
 * Gerado por scripts/gen_bearing_catalog.py — não editar à mão.
 */
class EngineeringCatalog
{
    public static function findBearing(string $code): ?array
    {
        $norm = self::normalizeCode($code);
        $all = self::bearings();
        if (isset($all[$norm])) {
            return $all[$norm];
        }
        foreach ($all as $row) {
            foreach ($row['aliases'] as $alias) {
                if (self::normalizeCode($alias) === $norm) {
                    return $row;
                }
            }
        }
        return null;
    }

    public static function search(string $q, int $limit = 50): array
    {
        $q = self::normalizeCode($q);
        if ($q === '') {
            return array_slice(array_values(self::bearings()), 0, $limit);
        }
        $out = [];
        foreach (self::bearings() as $row) {
            $hay = $row['code'] . implode('', $row['aliases']);
            if (strpos(self::normalizeCode($hay), $q) !== false) {
                $out[] = $row;
                if (count($out) >= $limit) {
                    break;
                }
            }
        }
        return $out;
    }

    public static function codes(): array
    {
        return array_keys(self::bearings());
    }

