    }

    public static function nlgiGrades(): array
    {
        return ['000', '00', '0', '1', '2', '3'];
    }

    public static function v100ForVg(float $vg, float $vi = 95.0): float
    {
        static $map = [
            2 => 1.0,
            3 => 1.2,
            5 => 1.6,
            7 => 2.1,
            10 => 2.6,
            15 => 3.3,
            22 => 4.3,
            32 => 5.4,
            46 => 6.8,
            68 => 8.8,
            100 => 11.4,
            150 => 14.8,
            220 => 19.0,
            320 => 24.2,
            460 => 30.5,
            680 => 38.0,
            1000 => 48.0,
            1500 => 60.0,
        ];
        $keys = array_keys($map);
        if (isset($map[(int) $vg])) {
            $base = $map[(int) $vg];
        } else {
            $lo = $keys[0];
            $hi = $keys[count($keys) - 1];
            foreach ($keys as $k) {
                if ($k <= $vg) { $lo = $k; }
                if ($k >= $vg) { $hi = $k; break; }
            }
            if ($hi === $lo) {
                $base = $map[$lo];
            } else {
                $t = ($vg - $lo) / max(0.001, ($hi - $lo));
                $base = $map[$lo] + $t * ($map[$hi] - $map[$lo]);
            }
        }
        $scale = 1.0 + (($vi - 95.0) * 0.0035);
        return round(max(0.8, $base * $scale), 2);
    }

    public static function normalizeCode(string $code): string
    {
        $code = strtoupper(trim($code));
        $code = preg_replace('/[^A-Z0-9]/', '', $code) ?? $code;
        $code = preg_replace('/^(SKF|FAG|NSK|NTN|TIMKEN|KOYO|NACHI|INA)/', '', $code) ?? $code;
        $suffixes = ['2RSR', '2RSH', '2RS', 'ZZ', '2Z', 'W33', 'C3', 'C4', 'E1', 'CC', 'CK', 'TVP', 'E'];
        $changed = true;
        while ($changed) {
            $changed = false;
            foreach ($suffixes as $sfx) {
                $len = strlen($sfx);
                if (strlen($code) > $len + 3 && substr($code, -$len) === $sfx) {
                    $code = substr($code, 0, -$len);
                    $changed = true;
                    break;
                }
            }
        }
        return $code;
    }

